/* 临时校验脚本：截图并测量「成交面积段结构」面板去掉新旧条后的填充情况 */
const { chromium } = require('playwright')

;(async () => {
  const browser = await chromium.launch({ headless: true })
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
  const errors = []
  page.on('pageerror', (e) => errors.push(String(e)))
  await page.goto('http://127.0.0.1:8092/index.html#/market-monitor', { waitUntil: 'networkidle' })
  await page.waitForTimeout(2500)
  await page.screenshot({ path: 'D:/repository/门户/test-results/mm-area-strip-after.png' })

  const info = await page.evaluate(() => {
    const h = [...document.querySelectorAll('h2')].find((e) => e.textContent.includes('成交面积段结构'))
    const panel = h && h.closest('.bg-white')
    const chart = panel && panel.querySelector('.flex-1.min-h-\\[120px\\]')
    const canvas = panel && panel.querySelector('canvas')
    const rect = (el) => (el ? { w: Math.round(el.getBoundingClientRect().width), h: Math.round(el.getBoundingClientRect().height), top: Math.round(el.getBoundingClientRect().top) } : null)
    return {
      panel: rect(panel),
      chart: rect(chart),
      canvas: rect(canvas),
      stripTextPresent: document.body.innerText.includes('新 25.3%') || document.body.innerText.includes('· 旧'),
      summaryTextPresent: document.body.innerText.includes('三档户型成交对比')
    }
  })
  console.log(JSON.stringify({ info, errors }, null, 2))
  await browser.close()
})().catch((e) => {
  console.error('FAILED:', e)
  process.exit(1)
})

